SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(e),'namespace',to_jsonb(n),'owner',pg_get_userbyid(e.extowner),'config_relations',(SELECT jsonb_agg(jsonb_build_object('oid',x,'identity',to_jsonb(pg_identify_object('pg_class'::regclass,x,0))) ORDER BY x) FROM unnest(e.extconfig) x)) ORDER BY e.oid),'[]'::jsonb) AS payload FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace) AS capture